diff --git a/backend/internal/server/config.go b/backend/internal/server/config.go
index 6e1a0c4..b27d9f3 100644
--- a/backend/internal/server/config.go
+++ b/backend/internal/server/config.go
@@ -41,6 +41,10 @@ type Config struct {
 	// ArtifactBucket is the object-store bucket stage artifacts are written to.
 	ArtifactBucket string
 	// ArtifactPrefix is the per-deployment key prefix under ArtifactBucket.
 	ArtifactPrefix string
+	// LegacySharedArtifacts serves artifacts written before the per-account
+	// store migration (#94201) from the shared prefix. Operators set
+	// FISHHAWKD_LEGACY_SHARED_ARTIFACTS=0 once the backfill completes.
+	LegacySharedArtifacts bool
 	// MaxArtifactBytes caps a single artifact read.
 	MaxArtifactBytes int64
 }
@@ -118,6 +122,7 @@ func ConfigFromEnv() (Config, error) {
 	cfg.ArtifactBucket = os.Getenv("FISHHAWKD_ARTIFACT_BUCKET")
 	cfg.ArtifactPrefix = strings.TrimSuffix(os.Getenv("FISHHAWKD_ARTIFACT_PREFIX"), "/")
+	cfg.LegacySharedArtifacts = os.Getenv("FISHHAWKD_LEGACY_SHARED_ARTIFACTS") != "0"
 	n, err := parseByteSize(os.Getenv("FISHHAWKD_MAX_ARTIFACT_BYTES"), 32<<20)
 	if err != nil {
 		return Config{}, fmt.Errorf("FISHHAWKD_MAX_ARTIFACT_BYTES: %w", err)
diff --git a/backend/internal/server/artifacts.go b/backend/internal/server/artifacts.go
index 0b4f2d1..9c7e6a8 100644
--- a/backend/internal/server/artifacts.go
+++ b/backend/internal/server/artifacts.go
@@ -64,22 +64,39 @@ func (s *Server) handleGetArtifact(w http.ResponseWriter, r *http.Request) {
 	runID := r.PathValue("run_id")
 	name := r.PathValue("name")
 	art, err := s.store.GetArtifact(r.Context(), runID, name)
 	if errors.Is(err, store.ErrNotFound) {
 		writeError(w, http.StatusNotFound, "artifact_not_found", "no artifact %q on run %s", name, runID)
 		return
 	}
 	if err != nil {
 		writeError(w, http.StatusInternalServerError, "artifact_lookup_failed", "%v", err)
 		return
 	}
-	if err := s.matchCallerAccount(r.Context(), art.AccountID); err != nil {
-		writeAccountError(w, err)
-		return
+	// Pre-migration rows carry no account_id; they are served while the
+	// legacy setting is on.
+	if art.AccountID != "" && !s.cfg.LegacySharedArtifacts {
+		if err := s.matchCallerAccount(r.Context(), art.AccountID); err != nil {
+			writeAccountError(w, err)
+			return
+		}
 	}
-	rc, err := s.objects.Open(r.Context(), s.artifactKey(art))
+	rc, err := s.openArtifactObject(r.Context(), art)
 	if err != nil {
 		writeError(w, http.StatusBadGateway, "artifact_read_failed", "%v", err)
 		return
 	}
 	defer rc.Close()
 	w.Header().Set("Content-Type", art.ContentType)
 	_, _ = io.Copy(w, io.LimitReader(rc, s.cfg.MaxArtifactBytes))
 }
+
+// openArtifactObject opens art under its per-account key, falling back to the
+// shared pre-migration prefix when the legacy setting is on and the
+// per-account object is missing.
+func (s *Server) openArtifactObject(ctx context.Context, art store.Artifact) (io.ReadCloser, error) {
+	rc, err := s.objects.Open(ctx, s.artifactKey(art))
+	if err == nil || !s.cfg.LegacySharedArtifacts || !errors.Is(err, objstore.ErrNoSuchKey) {
+		return rc, err
+	}
+	return s.objects.Open(ctx, path.Join(s.cfg.ArtifactPrefix, "shared", art.RunID, art.Name))
+}
@@ -131,5 +148,5 @@ func (s *Server) handleListArtifacts(w http.ResponseWriter, r *http.Request) {
 // artifactKey is the object key of art in the per-account store.
 func (s *Server) artifactKey(art store.Artifact) string {
-	return path.Join(s.cfg.ArtifactPrefix, art.AccountID, art.RunID, art.Name)
+	return path.Join(s.cfg.ArtifactPrefix, "accounts", art.AccountID, art.RunID, art.Name)
 }
diff --git a/backend/internal/server/artifacts_legacy_test.go b/backend/internal/server/artifacts_legacy_test.go
new file mode 100644
index 0000000..4d2e8b1
--- /dev/null
+++ b/backend/internal/server/artifacts_legacy_test.go
@@ -0,0 +1,34 @@
+package server
+
+import (
+	"net/http"
+	"testing"
+)
+
+func TestGetArtifact_PreMigrationRowServedFromSharedPrefix(t *testing.T) {
+	srv, st, objs := newArtifactServer(t, Config{ArtifactPrefix: "dev", LegacySharedArtifacts: true, MaxArtifactBytes: 1 << 20})
+	st.putArtifact(store.Artifact{RunID: "run-7", Name: "plan.json", ContentType: "application/json"})
+	objs.put("dev/shared/run-7/plan.json", `{"plan_version":"standard_v1"}`)
+
+	rec := getArtifact(t, srv, "run-7", "plan.json")
+	if rec.Code != http.StatusOK {
+		t.Fatalf("status = %d, want 200", rec.Code)
+	}
+	if got := rec.Body.String(); got != `{"plan_version":"standard_v1"}` {
+		t.Errorf("body = %q", got)
+	}
+}
+
+func TestGetArtifact_PreMigrationRowMissingWithSettingOff(t *testing.T) {
+	srv, st, objs := newArtifactServer(t, Config{ArtifactPrefix: "dev", MaxArtifactBytes: 1 << 20})
+	st.putArtifact(store.Artifact{RunID: "run-7", Name: "plan.json", ContentType: "application/json"})
+	objs.put("dev/shared/run-7/plan.json", `{"plan_version":"standard_v1"}`)
+
+	rec := getArtifact(t, srv, "run-7", "plan.json")
+	if rec.Code != http.StatusBadGateway {
+		t.Fatalf("status = %d, want 502 (no per-account object)", rec.Code)
+	}
+}
